function defineComponentGetter(object, key, path, _inner) {
  Object.defineProperty(object, key, {
    enumerable: true,
    get: function() {
      if(typeof _cache[path] === 'undefined') {
        _cache[path] = require(path);
        if(typeof _inner === 'string') {
          _cache[path] = _cache[path][_inner];
        }
      }
      return _cache[path];
    },
    set: function(v) {
      _cache[path] = v;
    }
  });
}

